import React, { useMemo } from 'react';
import { Box, Chip, Grid, Paper, Stack, Typography } from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { GHG_SCOPE_COLORS, formatCo2eFromKg } from '../../constants/carbonVisualization';
import { getGlossaryIllustration } from '../../constants/glossaryIllustrations';
import { getGlossaryTerm } from '../../constants/glossaryTerms';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { SCOPE_EXPLAINER_STRIP_LOCALE } from '../../i18n/glossaryLocale';
import {
  SCOPE_PICTURES,
  hottestCategoryId,
  resolveScopeCategories,
  type ScopePictureKey,
} from '../ghg/scopeCategoryModel';
import PlainLanguageExplainer from './PlainLanguageExplainer';

export type ScopeExplainerStripProps = {
  /** Scope 1 emissions in kg CO₂e */
  scope1Kg?: number;
  /** Scope 2 emissions in kg CO₂e */
  scope2Kg?: number;
  /** Scope 3 emissions in kg CO₂e */
  scope3Kg?: number;
  /** Compact density for dashboard embedding */
  compact?: boolean;
  /** Names which inventory the totals come from when pages share this widget. */
  inventoryLabel?: string;
  /** Live category kg. Missing keys stay label-only — numbers are never invented. */
  scope1Breakdown?: Record<string, number> | null;
  scope2Breakdown?: Record<string, number> | null;
  scope3Breakdown?: Record<string, number> | null;
};

const SCOPE_ITEMS = [
  { termId: 'scope1', kgKey: 'scope1Kg' as const, color: GHG_SCOPE_COLORS.scope1.fill },
  { termId: 'scope2', kgKey: 'scope2Kg' as const, color: GHG_SCOPE_COLORS.scope2.fill },
  { termId: 'scope3', kgKey: 'scope3Kg' as const, color: GHG_SCOPE_COLORS.scope3.fill },
] as const;

const ScopeExplainerStrip: React.FC<ScopeExplainerStripProps> = ({
  scope1Kg,
  scope2Kg,
  scope3Kg,
  compact = false,
  scope1Breakdown,
  scope2Breakdown,
  scope3Breakdown,
  inventoryLabel,
}) => {
  const theme = useTheme();
  const { locale } = useReadinessLocale();
  const ui = SCOPE_EXPLAINER_STRIP_LOCALE[locale];

  const kgByKey = useMemo(
    () => ({
      scope1Kg: Math.max(0, Number(scope1Kg) || 0),
      scope2Kg: Math.max(0, Number(scope2Kg) || 0),
      scope3Kg: Math.max(0, Number(scope3Kg) || 0),
    }),
    [scope1Kg, scope2Kg, scope3Kg]
  );

  const breakdownByScope = useMemo(
    () => ({
      scope1: scope1Breakdown,
      scope2: scope2Breakdown,
      scope3: scope3Breakdown,
    }),
    [scope1Breakdown, scope2Breakdown, scope3Breakdown]
  );

  const totalKg = kgByKey.scope1Kg + kgByKey.scope2Kg + kgByKey.scope3Kg;
  const hasEmissions = totalKg > 0;
  // DEEP-BUG-009: keep sibling scope cards on one unit (do not mix kg and t).
  const scopeDisplayUnit: 'kg' | 't' = totalKg >= 1000 ? 't' : 'kg';
  const imageHeight = compact ? 128 : 168;

  return (
    <Paper
      variant="outlined"
      sx={{
        p: { xs: 2, md: compact ? 2 : 2.5 },
        mb: 3,
        overflow: 'hidden',
        background: (t) =>
          t.palette.mode === 'dark'
            ? alpha(t.palette.background.paper, 0.9)
            : `linear-gradient(160deg, ${alpha('#ecfdf5', 0.55)} 0%, ${t.palette.background.paper} 42%, ${alpha('#f8fafc', 0.9)} 100%)`,
      }}
      data-testid="scope-explainer-strip"
    >
      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={1}
        alignItems={{ xs: 'flex-start', sm: 'baseline' }}
        justifyContent="space-between"
        sx={{ mb: 0.5 }}
      >
        <Typography variant="subtitle1" sx={{ fontWeight: 800, letterSpacing: '-0.01em' }}>
          {ui.title}
        </Typography>
        {hasEmissions ? (
          <Chip
            size="small"
            color="success"
            variant="outlined"
            label={`${ui.yourTotal}: ${formatCo2eFromKg(totalKg, { unit: scopeDisplayUnit })}`}
            sx={{ fontWeight: 700 }}
            data-testid="scope-explainer-total"
          />
        ) : null}
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: inventoryLabel ? 0.5 : 2, maxWidth: 720, lineHeight: 1.55 }}>
        {hasEmissions ? ui.subtitleWithEmissions : ui.subtitle}
      </Typography>
      {inventoryLabel ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
          {inventoryLabel}
        </Typography>
      ) : null}

      <Box
        component="figure"
        data-testid="scope-org-boundary"
        aria-label="Organization boundary with carbon footprint in each scope and category"
        sx={{
          m: 0,
          p: { xs: 1.25, md: 1.75 },
          border: '2px dashed',
          borderColor: '#0f766e',
          borderRadius: 2,
          bgcolor: alpha('#ecfdf5', theme.palette.mode === 'dark' ? 0.08 : 0.45),
        }}
      >
        <Typography component="figcaption" variant="subtitle2" sx={{ fontWeight: 800, color: '#0f766e', mb: 0.25 }}>
          Organization boundary
        </Typography>
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1.5, fontWeight: 700 }}>
          Burn · Buy · Beyond
        </Typography>
      <Grid container spacing={2}>
        {SCOPE_ITEMS.map(({ termId, kgKey, color }) => {
          const term = getGlossaryTerm(termId, locale);
          const illustration = getGlossaryIllustration(termId, locale);
          const picture = SCOPE_PICTURES[termId as ScopePictureKey];
          const label = term?.term
            ?? GHG_SCOPE_COLORS[termId as keyof typeof GHG_SCOPE_COLORS]?.label
            ?? termId;
          const kg = kgByKey[kgKey];
          const share = hasEmissions ? Math.round((kg / totalKg) * 100) : null;
          const categories = resolveScopeCategories(
            termId as ScopePictureKey,
            breakdownByScope[termId as ScopePictureKey]
          );
          const hottestId = hottestCategoryId(categories);

          return (
            <Grid item xs={12} md={4} key={termId}>
              <Box
                data-testid={`scope-explainer-card-${termId}`}
                sx={{
                  height: '100%',
                  minWidth: 0,
                  border: 1,
                  borderColor: alpha(color, 0.35),
                  borderRadius: 2,
                  overflow: 'hidden',
                  display: 'flex',
                  flexDirection: 'column',
                  bgcolor: 'background.paper',
                  boxShadow: `0 1px 0 ${alpha(color, 0.18)}`,
                  transition: 'transform 180ms ease, box-shadow 180ms ease',
                  '@media (prefers-reduced-motion: no-preference)': {
                    '&:hover': {
                      transform: 'translateY(-2px)',
                      boxShadow: `0 10px 24px ${alpha(color, 0.16)}`,
                    },
                  },
                }}
              >
                <Box
                    sx={{
                      position: 'relative',
                      width: '100%',
                      height: imageHeight,
                      borderBottom: 4,
                      borderColor: color,
                      bgcolor: alpha(color, theme.palette.mode === 'dark' ? 0.12 : 0.06),
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      p: 1,
                    }}
                  >
                    <Box
                      component="img"
                      src={picture.src}
                      alt={illustration?.alt || `${label} carbon footprint`}
                      sx={{
                        width: '100%',
                        height: '100%',
                        objectFit: 'contain',
                      }}
                    />
                    <Box
                      sx={{
                        position: 'absolute',
                        left: 10,
                        top: 10,
                        pointerEvents: 'none',
                      }}
                    >
                      <Chip
                        size="small"
                        label={label}
                        sx={{
                          fontWeight: 800,
                          bgcolor: alpha('#fff', 0.94),
                          color,
                          border: `1px solid ${alpha(color, 0.45)}`,
                        }}
                      />
                    </Box>
                    <Box
                      sx={{
                        position: 'absolute',
                        right: 10,
                        bottom: 10,
                        maxWidth: '72%',
                        pointerEvents: 'none',
                      }}
                    >
                      {hasEmissions ? (
                        <Box
                          data-testid={`scope-explainer-emissions-${termId}`}
                          sx={{
                            px: 1.15,
                            py: 0.6,
                            borderRadius: 1.5,
                            bgcolor: alpha('#0f172a', 0.86),
                            color: '#fff',
                            textAlign: 'right',
                            boxShadow: `0 4px 12px ${alpha('#0f172a', 0.25)}`,
                          }}
                        >
                          <Typography
                            variant="caption"
                            sx={{ display: 'block', opacity: 0.8, lineHeight: 1.1, fontWeight: 600 }}
                          >
                            {ui.emissionsLabel}
                          </Typography>
                          <Typography
                            variant="body2"
                            sx={{ fontWeight: 800, lineHeight: 1.25, whiteSpace: 'nowrap' }}
                          >
                            {formatCo2eFromKg(kg, { unit: scopeDisplayUnit })}
                          </Typography>
                          {share != null ? (
                            <Typography
                              variant="caption"
                              sx={{ display: 'block', opacity: 0.85, fontWeight: 700, whiteSpace: 'nowrap' }}
                            >
                              {share}% {ui.ofTotal}
                            </Typography>
                          ) : null}
                        </Box>
                      ) : (
                        <Chip
                          size="small"
                          label={ui.noDataYet}
                          sx={{
                            fontWeight: 700,
                            bgcolor: alpha('#fff', 0.92),
                            color: 'text.secondary',
                          }}
                          data-testid={`scope-explainer-empty-${termId}`}
                        />
                      )}
                    </Box>
                  </Box>
                <Stack spacing={0.6} sx={{ px: 1.25, pt: 1.25 }} data-testid={`scope-explainer-categories-${termId}`}>
                  {categories.map((row) => {
                    const highlighted = row.id === hottestId && row.kg != null && row.kg > 0;
                    const bar = row.kg != null && kg > 0 ? Math.min(100, Math.round((row.kg / kg) * 100)) : 0;
                    return (
                      <Box
                        key={row.id}
                        data-testid={`scope-category-${termId}-${row.id}`}
                        data-highlight={highlighted ? 'true' : 'false'}
                        sx={{
                          px: 1,
                          py: 0.55,
                          borderRadius: 1,
                          bgcolor: highlighted
                            ? alpha(color, 0.18)
                            : row.kg
                              ? alpha(color, 0.07)
                              : 'transparent',
                          outline: highlighted ? `1px solid ${alpha(color, 0.7)}` : 'none',
                        }}
                      >
                        <Stack direction="row" spacing={1} alignItems="baseline" justifyContent="space-between">
                          <Typography variant="caption" sx={{ fontWeight: highlighted ? 800 : 600, lineHeight: 1.3 }}>
                            {row.label}
                          </Typography>
                          {row.kg != null ? (
                            <Typography
                              variant="caption"
                              sx={{ fontWeight: 800, whiteSpace: 'nowrap', color: highlighted ? color : 'text.primary' }}
                            >
                              {formatCo2eFromKg(row.kg, { unit: scopeDisplayUnit })}
                            </Typography>
                          ) : null}
                        </Stack>
                        {row.kg != null && kg > 0 ? (
                          <Box sx={{ mt: 0.45, height: 5, borderRadius: 99, bgcolor: alpha(color, 0.15) }}>
                            <Box sx={{ width: `${Math.max(bar, 4)}%`, height: '100%', borderRadius: 99, bgcolor: color }} />
                          </Box>
                        ) : null}
                      </Box>
                    );
                  })}
                </Stack>
                <Box sx={{ p: 1.75, display: 'flex', flexDirection: 'column', gap: 0.75, flex: 1 }}>
                  <PlainLanguageExplainer termId={termId} variant="heading">
                    {label}
                  </PlainLanguageExplainer>
                  {term?.plain ? (
                    <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.45 }}>
                      {term.plain}
                    </Typography>
                  ) : null}
                  {term?.example ? (
                    <Typography variant="caption" color="text.secondary" sx={{ lineHeight: 1.4 }}>
                      {ui.examplePrefix} {term.example}
                    </Typography>
                  ) : null}
                </Box>
              </Box>
            </Grid>
          );
        })}
      </Grid>
      </Box>
    </Paper>
  );
};

export default ScopeExplainerStrip;
