export function normalizeBreakdownKey(key: string): string {
  return key.toLowerCase().replace(/[^a-z0-9]/g, '');
}

function humanizeKey(key: string): string {
  const words = key
    .replace(/([A-Z])/g, ' $1')
    .replace(/[_-]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ');
  if (!words) return key;
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/**
 * Map live inventory breakdown keys onto plain category rows.
 * Categories with no matching key stay label-only (kg null).
 */
export function resolveScopeCategories(
  scope: ScopePictureKey,
  breakdown?: Record<string, number> | null
): ScopeCategoryRow[] {
  const entries = Object.entries(breakdown || {}).filter(([, value]) => {
    const n = Number(value);
    return Number.isFinite(n) && n > 0;
  });
  const used = new Set<string>();
  const rows: ScopeCategoryRow[] = SCOPE_CATEGORY_DEFS[scope].map((category) => {
    const keySet = new Set(category.keys);
    let kg = 0;
    let matched = false;
    entries.forEach(([raw, value]) => {
      if (used.has(raw)) return;
      if (!keySet.has(normalizeBreakdownKey(raw))) return;
      kg += Number(value);
      used.add(raw);
      matched = true;
    });
    return { id: category.id, label: category.label, kg: matched ? kg : null };
  });

  entries.forEach(([raw, value]) => {
    if (used.has(raw)) return;
    rows.push({
      id: normalizeBreakdownKey(raw) || raw,
      label: humanizeKey(raw),
      kg: Number(value),
    });
  });

  return rows;
}

export function hottestCategoryId(rows: ScopeCategoryRow[]): string | null {
  let bestId: string | null = null;
  let bestKg = 0;
  rows.forEach((row) => {
    if (row.kg != null && row.kg > bestKg) {
      bestKg = row.kg;
      bestId = row.id;
    }
  });
  return bestId;
}
